"""Small bundled line icons; decoded by native Toga images, with no runtime imaging dependency."""
from base64 import b64decode
from functools import lru_cache
import toga

ICONS = {
    # nav_* are rendered from ui_new.sidebar.DestinationIcon by
    # Mobile/generate_navigation_icons.py; do not edit their bitmap data.
    'nav_settings': '',
    'nav_chat': '',
    'nav_documents': '',
    'nav_files': '',
    'nav_home': '',
    # folder_locked/folder_unlocked are generated by Mobile/generate_folder_icons.py
    # from services/folders/appearance.py. Edit that canonical vector source.
    # Passive browser indicators rendered from control_icons.ICONS on its 24-point grid.
    'storage_remote': '',
    'storage_local': '',
    'folder_locked': '',
    'folder_unlocked': '',
    'folder_document': '',
    'archives': '',
    'comic': '',
    'epub': '',
    'text': '',
    'folder_hub': '',
    'files': '',
    'documents': '',
    'books': '',
    'chat': '',
    'markdown': '',
}

@lru_cache(maxsize=12)
def icon(name):
    return toga.Image(src=b64decode(ICONS.get(name, ICONS["documents"])))
